/**
 * Transparent, explainable impact model.
 *
 * Every number shown to a user is computed here from disclosed assumptions.
 * The language model is never asked to invent figures — it only reframes the
 * actions and numbers this module produces.
 */

export const CURRENCIES = {
  INR: { symbol: '₹', rate: 83 },
  USD: { symbol: '$', rate: 1 },
  PKR: { symbol: '₨', rate: 280 },
  BDT: { symbol: '৳', rate: 110 },
  CNY: { symbol: '¥', rate: 7.2 },
  GBP: { symbol: '£', rate: 0.80 },
  EUR: { symbol: '€', rate: 0.92 },
  NGN: { symbol: '₦', rate: 1500 },
};

// Indoor PM2.5 generated by cooking, µg/m³ as a daily-average contribution for 1.5 h/day.
const COOKING_PM = { none: 0, electric: 2, lpg: 7, kerosene: 18, biomass: 26, coal: 32 };
// Winter heating contributions, µg/m³ daily average.
const HEATING_PM = { none: 0, electric: 0, gas: 1, wood: 24, coal: 30 };

const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, Number(n) || 0));
const round = (n, digits = 1) => {
  const f = 10 ** digits;
  return Math.round((Number(n) || 0) * f) / f;
};

export function normalizeProfile(raw = {}) {
  const commute = raw.commute || {};
  return {
    adults: clamp(raw.adults ?? 2, 0, 12),
    children: clamp(raw.children ?? 0, 0, 12),
    elders: clamp(raw.elders ?? 0, 0, 12),
    homeType: ['apartment', 'house'].includes(raw.homeType) ? raw.homeType : 'apartment',
    commute: {
      carKm: clamp(commute.carKm ?? 15, 0, 300),
      transitKm: clamp(commute.transitKm ?? 0, 0, 300),
      walkKm: clamp(commute.walkKm ?? 0, 0, 100),
      bikeKm: clamp(commute.bikeKm ?? 0, 0, 100),
    },
    cookingFuel: Object.hasOwn(COOKING_PM, raw.cookingFuel) ? raw.cookingFuel : 'lpg',
    cookingHours: clamp(raw.cookingHours ?? 1.5, 0, 8),
    heating: Object.hasOwn(HEATING_PM, raw.heating) ? raw.heating : 'electric',
    purifier: ['none', 'diy', 'hepa'].includes(raw.purifier) ? raw.purifier : 'none',
    indoorBurning: Boolean(raw.indoorBurning),
    sweeping: ['dry', 'wet'].includes(raw.sweeping) ? raw.sweeping : 'dry',
    maskUse: ['never', 'sometimes', 'always'].includes(raw.maskUse) ? raw.maskUse : 'never',
    windows: ['always', 'peakOnly', 'brief'].includes(raw.windows) ? raw.windows : 'always',
    burningWaste: Boolean(raw.burningWaste),
    redMeatMealsPerWeek: clamp(raw.redMeatMealsPerWeek ?? 3, 0, 21),
    currency: CURRENCIES[raw.currency] ? raw.currency : 'INR',
    concerns: Array.isArray(raw.concerns) ? raw.concerns.slice(0, 5) : [],
  };
}

/**
 * Build the household's baseline particle dose and the ingredients each action acts on.
 * Inhalation volumes: adult 15 m³/day, child 11, older adult 13 (activity-weighted averages).
 */
export function computeBaseline(profile, air) {
  const outdoor = clamp(air.pm25 ?? 60, 1, 500);

  let infiltration = profile.windows === 'always' ? 0.68 : profile.windows === 'peakOnly' ? 0.52 : 0.38;
  if (profile.homeType === 'apartment') infiltration *= 0.88;

  const outdoorDriven = outdoor * infiltration;
  const cookingBase = COOKING_PM[profile.cookingFuel] * (profile.cookingHours / 1.5);
  const heatingPM = HEATING_PM[profile.heating];
  const burnPM = profile.indoorBurning ? 12 : 0;
  const indoorPM = outdoorDriven + cookingBase + heatingPM + burnPM;

  const volume = {
    adults: profile.adults * 15,
    children: profile.children * 11,
    elders: profile.elders * 13,
  };
  const totalVolume = volume.adults + volume.children + volume.elders || 15;
  const people = profile.adults + profile.children + profile.elders || 1;

  const commuteKm = Object.values(profile.commute).reduce((a, b) => a + b, 0);
  const outdoorHours = clamp(commuteKm / 22 + 0.6, 0.5, 6);
  const indoorFraction = (24 - outdoorHours) / 24;
  const outdoorFraction = outdoorHours / 24;
  const sleepHours = 8;
  const activeIndoorHours = 24 - outdoorHours - sleepHours;

  const bedroomPM = outdoorDriven * 0.9 + (['wood', 'coal'].includes(profile.heating) ? heatingPM * 0.55 : 0);
  const sleepDose = totalVolume * bedroomPM * (sleepHours / 24);
  const activeDose = totalVolume * indoorPM * (Math.max(0, activeIndoorHours) / 24);
  const outdoorDose = totalVolume * outdoor * outdoorFraction;
  const totalDose = sleepDose + activeDose + outdoorDose;

  const outdoorDrivenDose = totalVolume * outdoorDriven * indoorFraction;

  const hourNow = new Date().getHours();
  const hourly = air.hourly || [];
  const atHour = (h) => {
    const hit = hourly.find((row) => Number(String(row.time).slice(0, 2)) === h);
    return hit ? hit.pm25 : outdoor;
  };

  return {
    outdoor,
    infiltration,
    outdoorDriven,
    cookingBase,
    heatingPM,
    burnPM,
    indoorPM,
    bedroomPM,
    totalVolume,
    people,
    outdoorHours,
    indoorFraction,
    outdoorFraction,
    sleepDose,
    activeDose,
    outdoorDose,
    totalDose,
    outdoorDrivenDose,
    hourNow,
    pmAtSchool: atHour(8),
    pmAtExercise: atHour(profile.commute.carKm ? 18 : hourNow),
    pmBest: air.bestWindow
      ? Math.min(air.bestWindow.avgPm25, air.pm25)
      : outdoor * 0.65,
  };
}

/** All actions applicable to this household, each carrying its own measured effect. */
export function buildActions(profile, air, b) {
  const rate = CURRENCIES[profile.currency].rate;
  const money = (usd) => round(usd * rate, rate < 10 ? 2 : 0);
  const actions = [];

  const add = (action) => {
    const doseSaved = Math.max(0, round(action.doseSaved || 0, 0));
    actions.push({
      ...action,
      doseSaved,
      co2Saved: round(action.co2Saved || 0, 2),
      costImpact: money(action.costImpact || 0),
      localG: round(action.localG || 0, 0),
      scope: action.scope || 'household',
      effort: action.effort || 'easy',
    });
  };

  // ---------- Indoor air ----------
  if (profile.purifier !== 'hepa' && (air.aqi > 60 || ['wood', 'coal'].includes(profile.heating))) {
    const remaining = profile.purifier === 'diy' ? 0.52 : 0.28;
    add({
      id: 'hepa-bedroom', category: 'indoor', icon: '🌬️', effort: 'medium',
      title: 'Put a true HEPA purifier in the bedroom',
      short: 'Clean the air you breathe for 8 hours every night.',
      when: 'Tonight, before bed',
      doseSaved: b.totalVolume * b.bedroomPM * (1 - remaining) * (8 / 24),
      co2Saved: -0.14, costImpact: -0.28,
      detail: `Choose a unit with a CADR of roughly ${Math.round(Math.max(80, b.bedroomPM * 2))} m³/h for a typical bedroom. Run it on medium with windows shut. A true HEPA filter captures ~99% of particles passing through it; real-room PM2.5 typically drops 60–75%.`,
      why: `You spend about 8 hours asleep in one room. On nights like this, that room alone can account for ${Math.round((b.sleepDose / b.totalDose) * 100)}% of your family's daily particle dose.`,
      steps: ['Match CADR to room size (≈ 10 × floor area in m²)', 'Keep the bedroom door and windows closed while it runs', 'Budget for a replacement filter every 3–6 months'],
    });
  }

  if (profile.purifier === 'none') {
    add({
      id: 'diy-filter', category: 'indoor', icon: '🌀', effort: 'easy',
      title: 'Build a box-fan filter for under a day’s wages',
      short: 'A MERV-13 filter taped to a normal fan cuts bedroom particles.',
      when: 'This afternoon',
      doseSaved: b.totalVolume * b.bedroomPM * 0.45 * (8 / 24),
      co2Saved: -0.02, costImpact: -0.07,
      detail: 'Tape a MERV-13 (or F7) furnace filter to the back of a box fan, seal the edges with cardboard, and run it in the bedroom with the window closed. Expect roughly 40–50% lower PM2.5 in that room.',
      why: 'It delivers a meaningful share of a purifier’s benefit at a fraction of the cost — a good first step if a HEPA unit is out of reach.',
      steps: ['Use a 20-inch box fan and a MERV-13 pleated filter', 'Seal gaps with tape so air cannot bypass the filter', 'Never leave a DIY rig unattended or near curtains'],
    });
  }

  if (['biomass', 'coal', 'kerosene'].includes(profile.cookingFuel)) {
    const target = 7 * (profile.cookingHours / 1.5);
    const co2 = { coal: 1.7, biomass: 0.7, kerosene: 1.2 }[profile.cookingFuel];
    add({
      id: 'clean-cooking', category: 'indoor', icon: '🍳', effort: 'medium',
      title: 'Move cooking off solid fuel',
      short: 'Switch this week’s cooking to LPG or an induction/electric stove.',
      when: 'Starting with the next meal',
      doseSaved: b.totalVolume * Math.max(0, b.cookingBase - target) * b.indoorFraction,
      co2Saved: co2, costImpact: 0.08,
      detail: `Your current ${profile.cookingFuel} stove adds about ${Math.round(b.cookingBase)} µg/m³ to the home's daily average. LPG or electric drops that to ~7. Also cuts black carbon — a short-lived climate pollutant that is especially damaging in winter smog.`,
      why: `Cooking smoke is the biggest source you control inside the house. Changing it protects the people standing closest to the stove — often the women and children in the family.`,
      steps: ['Start with one meal a day if a full switch is costly', 'Ventilate while cooking and use a chimney/hood where possible', 'Keep children out of the kitchen during high-smoke cooking'],
    });
  }

  if (b.cookingBase > 3) {
    add({
      id: 'range-hood', category: 'indoor', icon: '💨', effort: 'easy',
      title: 'Vent cooking smoke outdoors',
      short: 'Use a vented hood or open a window on the downwind side while cooking.',
      when: 'Every cooking session',
      doseSaved: b.totalVolume * Math.min(b.cookingBase, 18) * 0.5 * b.indoorFraction,
      co2Saved: 0, costImpact: 0,
      detail: 'A hood that vents outside removes roughly half of cooking-generated particles before they spread through the home. A recirculating hood with a grease filter helps less; open a window too.',
      why: `Cooking contributes ~${Math.round(b.cookingBase)} µg/m³ to your indoor air. Capturing it at the source is cheaper than filtering the whole home later.`,
      steps: ['Switch the hood on before the flame, leave it 5 minutes after', 'Clean the filter weekly', 'If there is no hood, cook near an open window with a fan blowing out'],
    });
  }

  if (profile.indoorBurning) {
    add({
      id: 'no-indoor-burning', category: 'indoor', icon: '🕯️', effort: 'easy',
      title: 'Pause incense, coils and candles indoors',
      short: 'Just one mosquito coil or a few incense sticks can spike indoor PM2.5.',
      when: 'From today',
      doseSaved: b.totalVolume * b.burnPM * 0.9 * b.indoorFraction,
      co2Saved: 0, costImpact: 0.02,
      detail: 'A single mosquito coil can emit as much PM2.5 as dozens of cigarettes over an evening. Swap to an electric vapouriser or mosquito net, and move incense to a balcony or doorway.',
      why: `This habit alone adds ~${b.burnPM} µg/m³ to your daily indoor average — the easiest source to remove.`,
      steps: ['Use an electric vapouriser instead of coils', 'Keep incense and candles out of bedrooms', 'If you must burn something, do it by an open window'],
    });
  }

  if (['wood', 'coal'].includes(profile.heating)) {
    add({
      id: 'warm-layers', category: 'indoor', icon: '🧣', effort: 'medium',
      title: 'Warm the person, not the smoke',
      short: 'Layer up and use an electric blanket or clean heater instead of wood/coal.',
      when: 'This week',
      doseSaved: b.totalVolume * b.heatingPM * 0.85 * b.indoorFraction,
      co2Saved: 1.8, costImpact: -0.22,
      detail: `Solid-fuel heating adds ~${b.heatingPM} µg/m³ indoors and pollutes the whole neighbourhood's air. Thermal layers, a hot water bottle and a sealed electric room heater give the same comfort with far less smoke.`,
      why: 'Winter smog is worse on still, cold evenings — exactly when wood and coal burning peaks. Heating is a source you can change without losing warmth.',
      steps: ['Try an electric blanket for sleeping', 'Seal draughts before turning up any heater', 'Never burn treated wood, plastic or waste for warmth'],
    });
  }

  if (profile.windows !== 'brief') {
    const targetInf = profile.windows === 'always' ? 0.42 : 0.34;
    const reduction = clamp((b.infiltration - targetInf) / b.infiltration, 0.05, 0.7);
    add({
      id: 'vent-timing', category: 'indoor', icon: '🪟', effort: 'easy',
      title: `Shut windows at peak hours, air out at ${air.bestWindow?.start || 'midday'}`,
      short: 'Ten minutes of cross-ventilation in the cleanest hour beats all-day open windows.',
      when: air.bestWindow ? `${air.bestWindow.start}–${air.bestWindow.end}` : 'Mid-afternoon',
      doseSaved: b.outdoorDrivenDose * reduction,
      co2Saved: 0, costImpact: 0,
      detail: `Keep windows closed during morning and evening traffic peaks. Open two opposite windows for 8–10 minutes around ${air.bestWindow?.start || '15:00'}, when outdoor PM2.5 is forecast near ${Math.round(air.bestWindow?.avgPm25 ?? b.outdoor * 0.65)} µg/m³, then close them again.`,
      why: `Outdoor air entering your home currently drives ~${Math.round((b.outdoorDrivenDose / b.totalDose) * 100)}% of your family's dose. Timing the openings cuts that without stuffy rooms.`,
      steps: ['Check the hourly strip before opening windows', 'Use a kitchen or bathroom exhaust fan briefly to pull air through', 'Seal the biggest gaps under doors with a rolled towel'],
    });
  }

  if (profile.sweeping === 'dry') {
    add({
      id: 'wet-mop', category: 'indoor', icon: '🧽', effort: 'easy',
      title: 'Swap dry sweeping for a damp mop',
      short: 'Dry sweeping lifts settled dust straight back into breathing air.',
      when: 'Daily, after the children leave for school',
      doseSaved: (b.sleepDose + b.activeDose) * 0.08,
      co2Saved: 0, costImpact: 0,
      detail: 'Use a slightly damp mop or a cloth with a drop of detergent. If you vacuum, choose one with a HEPA filter — a normal vacuum can make indoor PM2.5 worse.',
      why: 'Settled dust is a reservoir of PM2.5, lead and allergens. Wet cleaning removes it instead of re-suspending it at child height.',
      steps: ['Mop rather than sweep hard floors', 'Wipe window sills weekly', 'Shake rugs outside only when outdoor air is cleaner'],
    });
  }

  if (profile.humidityNote !== false) {
    // Kept in the library as a low-cost comfort/support action with no invented particle number.
    add({
      id: 'humidity', category: 'indoor', icon: '💧', effort: 'easy',
      title: 'Keep indoor humidity near 40–60%',
      short: 'Comfortable airways handle polluted air better; very dry air aggravates coughs.',
      when: 'Check weekly',
      doseSaved: 0, co2Saved: 0, costImpact: 0, noMetric: true,
      detail: 'A cheap hygrometer guides this. In dry winter air, a bowl of water or a humidifier helps; in damp homes, ventilate and fix leaks to prevent mould.',
      why: 'Humidity does not remove particles, but it reduces irritation and helps salt-based masks and nasal passages work comfortably.',
      steps: ['Buy a basic hygrometer', 'Aim for 40–60%, not saturated', 'Clean humidifiers weekly to avoid mould'],
    });
  }

  // ---------- Personal exposure ----------
  if (air.aqi > 100 && profile.maskUse !== 'always') {
    const factor = profile.maskUse === 'never' ? 0.85 : 0.4;
    add({
      id: 'mask', category: 'habits', icon: '😷', effort: 'easy',
      title: 'Wear a well-fitted N95/FFP2 outside',
      short: 'A snug respirator filters ~90%+ of fine particles you would otherwise inhale.',
      when: 'Any trip outdoors today',
      doseSaved: b.outdoorDose * factor,
      co2Saved: 0, costImpact: -0.12,
      detail: 'Look for N95, FFP2 or KN95 with a nose wire and a tight seal. Cloth and surgical masks offer little protection against PM2.5. Children need properly sized masks; masks are not recommended for very young children or people with breathing difficulty without medical advice.',
      why: `Your commute and errands account for ~${Math.round((b.outdoorDose / b.totalDose) * 100)}% of the family's daily particle dose — this targets that share directly.`,
      steps: ['Do a seal check each time: cover the mask and breathe in/out', 'Replace when damp, dirty or hard to breathe through', 'Keep a spare in your bag or school kit'],
    });
  }

  if (b.pmAtExercise - b.pmBest > 15) {
    add({
      id: 'exercise-timing', category: 'habits', icon: '🏃', effort: 'easy',
      title: `Move outdoor play to ${air.bestWindow?.start || 'the cleanest hour'}`,
      short: 'Same exercise, far fewer particles inhaled per breath.',
      when: air.bestWindow ? `${air.bestWindow.start}–${air.bestWindow.end}` : 'Mid-afternoon',
      doseSaved: 45 * Math.max(1, profile.adults + profile.children * 0.7) * Math.max(0, b.pmAtExercise - b.pmBest) * 1.3,
      co2Saved: 0, costImpact: 0,
      detail: `During exercise people breathe 3–5× more air. Moving a 1-hour walk or cricket game from a ${Math.round(b.pmAtExercise)} µg/m³ hour to a ${Math.round(b.pmBest)} µg/m³ hour cuts the dose sharply without changing the activity.`,
      why: 'The time of day can matter almost as much as the place. The hourly forecast shows a noticeably cleaner window today.',
      steps: ['Use the hourly strip to pick a slot', 'On hazardous days, choose indoor activity instead', 'Keep children’s school sports indoors when the AQI alert is high'],
    });
  }

  if (profile.children > 0 && air.aqi > 100) {
    add({
      id: 'school-air-alert', category: 'habits', icon: '🎒', effort: 'easy',
      title: 'Set a school-day air alert',
      short: 'Check AQI before the school run; shift outdoor play when it is high.',
      when: 'Every morning at 7:30',
      doseSaved: profile.children * 11 * 1.5 * Math.max(0, b.pmAtSchool - 55),
      co2Saved: 0, costImpact: 0,
      detail: 'Children breathe more air per kg of body weight and their lungs are still developing. On high-AQI mornings, ask the school to keep assembly and sports indoors, and walk the quieter-road route.',
      why: 'A short morning assembly at a busy roadside gate can be a surprisingly large part of a child’s daily exposure.',
      steps: ['Put an AQI check in the morning routine', 'Talk to the school about indoor play days', 'Choose back streets over main roads on the walk'],
    });
  }

  // ---------- Low-emission living ----------
  if (profile.commute.carKm > 0) {
    const shifted = profile.commute.carKm * 0.5;
    add({
      id: 'transit-swap', category: 'commute', icon: '🚇', effort: 'medium',
      title: 'Trade half your car kilometres for transit',
      short: 'One bus or metro ride replaces the dirtiest half of your daily drive.',
      when: 'Next working day',
      doseSaved: 0,
      co2Saved: shifted * (0.192 - 0.055),
      costImpact: shifted * (0.11 - 0.045),
      localG: shifted * 0.42,
      detail: `Driving emits ~192 g CO₂e/km; a bus or metro is closer to 55 g/km per passenger. Shifting ${Math.round(shifted)} km/day also avoids roughly ${Math.round(shifted * 0.42)} g of local NOx and particle precursors on your streets. On very polluted days choose an enclosed, filtered bus or metro rather than cycling beside traffic.`,
      why: 'Traffic is the main source of winter smog in most cities. Fewer car-kilometres improve the air your whole neighbourhood shares — including your own front door.',
      steps: ['Try it twice a week first', 'Combine trips into one loop', 'If you must drive, keep windows up and use recirculation in tunnels and jams'],
    });

    add({
      id: 'no-idling', category: 'commute', icon: '🚗', effort: 'easy',
      title: 'Skip the warm-up idling',
      short: 'Modern engines warm faster while driving — idling just fills the air with exhaust.',
      when: 'Every cold morning',
      doseSaved: 0, co2Saved: 0.16, costImpact: 0.16, localG: 8,
      detail: 'Five minutes of idling burns fuel while going nowhere and releases exhaust right where children wait for the school bus. Start driving gently after ~30 seconds.',
      why: 'It costs nothing to change and cuts emissions at the exact moment and place where families are most exposed.',
      steps: ['Limit idling to 30 seconds', 'Use a blanket or coat instead of running the engine for heat', 'Turn off at long pick-up queues'],
    });

    add({
      id: 'community-carpool', category: 'community', icon: '🤝', effort: 'medium',
      title: 'Start a school-run carpool rota',
      short: 'Four families sharing one ride removes three cars from the gate.',
      when: 'This week',
      doseSaved: 0, co2Saved: 0.8, costImpact: 0.25, localG: 40,
      scope: 'community',
      detail: 'A four-family rota cuts school-gate traffic by up to 75% on those days, along with the exhaust plume children walk through. Rotate who drives so the benefit and cost are shared.',
      why: 'A single household can clean its own home, but only a street working together can clean the air outside it.',
      steps: ['Find 3 neighbours on the same route', 'Agree a 4-day rota and a rain plan', 'Ask the school to mark a no-idling zone'],
    });
  }

  if (profile.burningWaste) {
    add({
      id: 'no-burn-waste', category: 'community', icon: '🔥', effort: 'medium',
      title: 'End the garden-waste burn',
      short: 'Leaves and plastic burned in the open poison the whole lane.',
      when: 'This weekend',
      doseSaved: b.totalVolume * 7 * b.indoorFraction * 0.6,
      co2Saved: 0.6, costImpact: 0, localG: 250,
      detail: 'Open burning emits PM2.5, black carbon and toxic gases right at breathing height. Compost leaves, hand them to the municipal pickup, or start a neighbourhood collection point. Never burn plastic or treated wood.',
      why: 'One small pile can raise PM2.5 across several homes for hours. This is the clearest case where one family’s habit becomes everyone’s problem.',
      steps: ['Start a compost bin for leaves', 'Keep cardboard and plastic out of any burn pile', 'Suggest a shared green-waste collection to your neighbours'],
    });
  }

  if (profile.redMeatMealsPerWeek >= 2) {
    add({
      id: 'plant-meal', category: 'diet', icon: '🫘', effort: 'easy',
      title: 'Make two meals a week pulse-based',
      short: 'Lentils or beans instead of red meat cut emissions and cooking smoke.',
      when: 'Twice a week',
      doseSaved: 0,
      co2Saved: (profile.redMeatMealsPerWeek / 7) * 1.5,
      costImpact: 0.12,
      detail: 'Swapping one red-meat meal for lentils or beans saves roughly 1.5 kg CO₂e per meal on average and is usually cheaper. Pressure-cooked pulses also mean less time over a smoky stove.',
      why: 'Food choices are a steady, low-effort way to reduce your household’s footprint without changing where you live or work.',
      steps: ['Pick two familiar dishes and swap the protein', 'Batch-cook pulses to save fuel', 'Keep the family’s favourite dishes on the other days'],
    });
  }

  return actions;
}

/** Rank actions by household fit, then return a diversified short plan. */
export function rankActions(actions, profile) {
  const concerns = profile.concerns || [];
  const wDose = concerns.some((c) => ['child-asthma', 'elder', 'pregnancy'].includes(c)) ? 2.2 : 1.4;
  const wCo2 = concerns.includes('climate') ? 2.0 : 1.0;
  const wCost = concerns.includes('budget') ? 2.0 : 0.7;

  const max = (key) => Math.max(1, ...actions.map((a) => Math.abs(a[key] || 0)));
  const maxDose = max('doseSaved');
  const maxCo2 = max('co2Saved');
  const maxCost = max('costImpact');

  return actions
    .filter((a) => !a.noMetric || a.id === 'humidity')
    .map((a) => {
      let score = (a.doseSaved / maxDose) * wDose
        + (Math.max(0, a.co2Saved) / maxCo2) * wCo2
        + (Math.max(0, a.costImpact) / maxCost) * wCost;
      if (a.effort === 'easy') score += 0.25;
      if (a.category === 'indoor' && concerns.some((c) => ['child-asthma', 'elder', 'pregnancy'].includes(c))) score += 0.3;
      if (a.scope === 'community') score += 0.1;
      if (a.noMetric) score -= 0.6;
      return { ...a, score: round(score, 3) };
    })
    .sort((a, b) => b.score - a.score);
}

export function selectPlan(ranked, limit = 6, options = {}) {
  const picked = [];
  const perCategory = {};
  for (const action of ranked) {
    const count = perCategory[action.category] || 0;
    if (count >= 3 && picked.length < limit) continue;
    if (action.noMetric && picked.length >= 3) continue;
    picked.push(action);
    perCategory[action.category] = count + 1;
    if (picked.length >= limit) break;
  }

  const guaranteed = new Set();
  const mustInclude = options.mustInclude || [];
  for (const id of mustInclude) {
    if (picked.some((a) => a.id === id)) { guaranteed.add(id); continue; }
    const candidate = ranked.find((a) => a.id === id);
    if (!candidate) continue;
    const replaceAt = picked.reduce((worst, a, i) => (
      !guaranteed.has(a.id) && a.score < picked[worst].score ? i : worst
    ), 0);
    picked[replaceAt] = candidate;
    guaranteed.add(id);
  }

  if (!picked.some((a) => a.effort === 'easy')) {
    const easy = ranked.find((a) => a.effort === 'easy' && !picked.includes(a));
    if (easy) picked[picked.length - 1] = easy;
  }
  return picked.map(({ score, ...action }) => action);
}

/**
 * Translate an action id into the exposure component it changes. Applying these
 * sequentially (rather than adding stand-alone savings) prevents double-counting
 * when, for example, a purifier and reduced infiltration act on the same air.
 */
function effectFor(id, profile, b) {
  switch (id) {
    case 'hepa-bedroom': return { bedroom: profile.purifier === 'diy' ? 0.52 : 0.28 };
    case 'diy-filter': return { bedroom: 0.55 };
    case 'clean-cooking': return { cooking: Math.min(1, (7 * (profile.cookingHours / 1.5)) / Math.max(1, b.cookingBase)) };
    case 'range-hood': return { cooking: 0.5 };
    case 'no-indoor-burning': return { burn: 0.1 };
    case 'warm-layers': return { heating: 0.15 };
    case 'vent-timing': return { infiltration: (profile.windows === 'always' ? 0.42 : 0.34) / Math.max(0.01, b.infiltration) };
    case 'wet-mop': return { indoor: 0.92 };
    case 'no-burn-waste': return { indoor: 0.9 };
    case 'mask': return { outdoor: profile.maskUse === 'never' ? 0.15 : 0.6 };
    case 'exercise-timing': {
      const saved = 45 * Math.max(1, profile.adults + profile.children * 0.7) * Math.max(0, b.pmAtExercise - b.pmBest) * 1.3;
      return { outdoor: clamp(1 - saved / Math.max(1, b.outdoorDose), 0, 1) };
    }
    case 'school-air-alert': {
      const saved = profile.children * 11 * 1.5 * Math.max(0, b.pmAtSchool - 55);
      return { outdoor: clamp(1 - saved / Math.max(1, b.outdoorDose), 0, 1) };
    }
    case 'school-route': return { outdoor: 0.8 };
    case 'clean-room': return { indoor: 0.9 };
    case 'recirculate': return { outdoor: 0.85 };
    case 'no-burn-pledge': return { indoor: 0.95 };
    default: return {};
  }
}

/** Recompute total inhaled dose after applying a set of interventions in sequence. */
export function simulateDose(actions, baseline, profile) {
  let outdoorDriven = baseline.outdoorDriven;
  let cooking = baseline.cookingBase;
  let heating = baseline.heatingPM;
  let burn = baseline.burnPM;
  let indoorFactor = 1;
  let bedroomFactor = 1;
  let outdoorFactor = 1;

  for (const action of actions) {
    const e = effectFor(action.id, profile, baseline);
    if (e.infiltration) outdoorDriven *= clamp(e.infiltration, 0, 1);
    if (e.cooking) cooking *= clamp(e.cooking, 0, 1);
    if (e.heating) heating *= clamp(e.heating, 0, 1);
    if (e.burn) burn *= clamp(e.burn, 0, 1);
    if (e.indoor) indoorFactor *= clamp(e.indoor, 0, 1);
    if (e.bedroom) bedroomFactor *= clamp(e.bedroom, 0, 1);
    if (e.outdoor) outdoorFactor *= clamp(e.outdoor, 0, 1);
  }

  const volume = baseline.totalVolume;
  const solidHeat = ['wood', 'coal'].includes(profile.heating);
  const bedroomPM = outdoorDriven * 0.9 + (solidHeat ? heating * 0.55 : 0);
  const indoorPM = outdoorDriven + cooking + heating + burn;
  const activeHours = Math.max(0, 24 - baseline.outdoorHours - 8);
  const sleep = volume * bedroomPM * (8 / 24) * indoorFactor * bedroomFactor;
  const active = volume * indoorPM * (activeHours / 24) * indoorFactor;
  const outdoor = baseline.outdoorDose * outdoorFactor;
  return { total: sleep + active + outdoor, sleep, active, outdoor };
}

export function summarize(actions, baseline, profile) {
  const household = actions.filter((a) => a.scope === 'household');
  const after = simulateDose(household, baseline, profile);
  const doseSaved = Math.max(0, baseline.totalDose - after.total);
  const pct = clamp(round((doseSaved / Math.max(1, baseline.totalDose)) * 100, 0), 0, 85);
  const co2Saved = round(actions.reduce((s, a) => s + Math.max(0, a.co2Saved), 0), 1);
  const digits = (CURRENCIES[profile?.currency]?.rate || 83) < 10 ? 2 : 0;
  const costImpact = round(actions.reduce((s, a) => s + a.costImpact, 0), digits);
  const localG = Math.round(actions.reduce((s, a) => s + a.localG, 0));
  return {
    doseSaved: Math.round(doseSaved),
    doseAfter: Math.round(after.total),
    doseReductionPct: pct,
    co2Saved,
    equivalentCarKm: Math.round(co2Saved / 0.192),
    localG,
    costImpact,
  };
}

